mod solution;

fn main() {
    let cases = [
    (r#"push4 push7 push2 delete2 min"#, r#"4"#),
    (r#"push5 push1 delete1 min"#, r#"5"#),
    (r#"
push5 push1 delete1 min
"#, r#"5"#),
    (r#"  
push4 push7 push2 delete2 min
  "#, r#"4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS lazy-heap-deletion");
}
